import crypto from 'crypto';
import { KeyManagementService } from '../security/KeyManagementService';
import {
  EvidenceRecord,
  ManifestVerificationState,
  NormalizedFinding,
  SignedEvidenceManifest,
  Software,
  ToolExecutionRecord,
  VeracityCheckResult,
} from '../types/benchmark';

export const GENESIS_EVIDENCE_HASH = '0'.repeat(64);

function sha256Hex(payload: string): string {
  return crypto.createHash('sha256').update(payload, 'utf8').digest('hex');
}

function hmacSha256Hex(payload: string, secret: string): string {
  return crypto.createHmac('sha256', secret).update(payload, 'utf8').digest('hex');
}

export function computeCanonicalEvidenceHash(
  record: Omit<EvidenceRecord, 'sha256'>,
  previousRecordSha256: string
): string {
  const canonicalPayload = JSON.stringify({
    id: record.id,
    runId: record.runId,
    softwareId: record.softwareId,
    softwareName: record.softwareName,
    version: record.version,
    commitHash: record.commitHash || '',
    sourceHash: record.sourceHash || '',
    criterionId: record.criterionId || '',
    evidenceType: record.evidenceType || 'STATIC_AST_FINDING',
    origin: record.origin || 'WINHOOD_ENGINE',
    responsibleActor: record.responsibleActor || 'system',
    category: record.category,
    toolName: record.toolName,
    toolVersion: record.toolVersion,
    timestamp: record.timestamp,
    resultSummary: record.resultSummary,
    severity: record.severity,
    fileOrComponent: record.fileOrComponent,
    validationStatus: record.validationStatus,
    rawPayloadPreview: record.rawPayloadPreview,
    immutableIndex: record.immutableIndex,
    previousRecordSha256,
  });
  return sha256Hex(canonicalPayload);
}

export function buildVerifiableEvidenceChain(params: {
  runId: string;
  softwares: Software[];
  findings: NormalizedFinding[];
  toolExecutions: ToolExecutionRecord[];
  veracityResults: VeracityCheckResult[];
  responsibleActor?: string;
}): EvidenceRecord[] {
  const {
    runId,
    softwares,
    findings,
    toolExecutions,
    veracityResults,
    responsibleActor = 'winhood-audit-engine',
  } = params;

  const softwareById = new Map<string, Software>();
  for (const sw of softwares) {
    softwareById.set(sw.id, sw);
  }

  const evidenceChain: EvidenceRecord[] = [];
  let previousHash = GENESIS_EVIDENCE_HASH;
  let immutableIndex = 0;

  // 1. Record Veracity Attestations for each Software
  for (const vr of veracityResults) {
    const sw = softwareById.get(vr.softwareId);
    const baseRecord: Omit<EvidenceRecord, 'sha256'> = {
      id: `ev-veracity-${runId}-${vr.softwareId}-${immutableIndex}`,
      runId,
      softwareId: vr.softwareId,
      softwareName: vr.softwareName,
      version: sw?.version || 'unknown',
      commitHash: sw?.commitHash || 'NOT_DECLARED',
      sourceHash: sw?.packageSha256 || 'UNVERIFIED',
      criterionId: 'VERACITY-19-CHECKS',
      evidenceType: 'VERACITY_ATTESTATION',
      origin: sw?.dataOrigin || 'USER_SOURCE',
      responsibleActor,
      category: 'VERACITY_AUDIT',
      toolName: 'WinHood Veracity & Provenance Auditor',
      toolVersion: '4.2.0',
      timestamp: vr.auditedAt,
      resultSummary: `Classificação=${vr.overallClassification} | Cobertura=${vr.overallCoveragePercent}% | Elegível=${vr.checks.eligibleForScoring}`,
      severity: vr.checks.eligibleForScoring ? 'INFO' : 'HIGH',
      fileOrComponent: 'SOURCE_MANIFEST',
      validationStatus: vr.overallClassification,
      rawPayloadPreview: JSON.stringify({
        overallClassification: vr.overallClassification,
        eligibleForScoring: vr.checks.eligibleForScoring,
        warnings: vr.warnings,
        blockingReasons: vr.blockingReasons,
      }),
      immutableIndex,
      previousRecordSha256: previousHash,
    };
    const recordHash = computeCanonicalEvidenceHash(baseRecord, previousHash);
    evidenceChain.push({
      ...baseRecord,
      sha256: recordHash,
    });
    previousHash = recordHash;
    immutableIndex += 1;
  }

  // 2. Record Tool Execution Proofs
  for (const exec of toolExecutions) {
    const sw = softwareById.get(exec.softwareId);
    const baseRecord: Omit<EvidenceRecord, 'sha256'> = {
      id: `ev-exec-${runId}-${exec.id}-${immutableIndex}`,
      runId,
      softwareId: exec.softwareId,
      softwareName: sw?.name || exec.softwareId,
      version: sw?.version || 'unknown',
      commitHash: exec.commitHash || sw?.commitHash || 'NOT_DECLARED',
      sourceHash: exec.sourceHash || sw?.packageSha256 || 'UNVERIFIED',
      criterionId: `TOOL-${exec.toolId}`,
      evidenceType: 'TOOL_RAW_OUTPUT',
      origin: exec.executionMethod || 'NATIVE_AST_ENGINE',
      responsibleActor,
      category: exec.canonicalFormat,
      toolName: exec.toolName,
      toolVersion: exec.toolVersion,
      timestamp: exec.completedAt,
      resultSummary: `Status=${exec.veracityStatus} | Método=${exec.executionMethod || 'NATIVE_AST_ENGINE'} | Arquivos=${exec.analyzedFilesCount}/${exec.eligibleFilesCount} | Exit=${exec.exitCode} | Duração=${exec.durationMs}ms`,
      severity: exec.veracityStatus === 'SUCCESS_VALIDATED' ? 'INFO' : 'LOW',
      fileOrComponent: exec.workingDirectory || sw?.inventory?.isolatedStoragePath || 'workspace',
      validationStatus: exec.veracityStatus,
      rawPayloadPreview: (exec.stdout || exec.logs.join(' | ')).slice(0, 400),
      immutableIndex,
      previousRecordSha256: previousHash,
    };
    const recordHash = computeCanonicalEvidenceHash(baseRecord, previousHash);
    evidenceChain.push({
      ...baseRecord,
      sha256: recordHash,
    });
    previousHash = recordHash;
    immutableIndex += 1;
  }

  // 3. Record Individual Findings with Code Location & Hash
  for (const f of findings) {
    const sw = softwareById.get(f.softwareId);
    const baseRecord: Omit<EvidenceRecord, 'sha256'> = {
      id: `ev-finding-${runId}-${f.id}-${immutableIndex}`,
      runId,
      softwareId: f.softwareId,
      softwareName: f.softwareName,
      version: f.softwareVersion,
      commitHash: sw?.commitHash || 'NOT_DECLARED',
      sourceHash: sw?.packageSha256 || 'UNVERIFIED',
      criterionId: f.originalRuleId,
      evidenceType: 'STATIC_AST_FINDING',
      origin: f.originType || 'WINHOOD_NATIVE_STATIC',
      responsibleActor,
      category: f.category,
      toolName: f.toolName,
      toolVersion: f.toolVersion,
      timestamp: f.collectedAt,
      resultSummary: `[${f.severity}] ${f.originalRuleId}: ${f.title} (${f.filePath}:${f.lineNumber})`,
      severity: f.severity,
      fileOrComponent: `${f.filePath}:${f.lineNumber}`,
      validationStatus: 'SUCCESS_VALIDATED',
      rawPayloadPreview: f.snippet.slice(0, 320),
      immutableIndex,
      previousRecordSha256: previousHash,
    };
    const recordHash = computeCanonicalEvidenceHash(baseRecord, previousHash);
    evidenceChain.push({
      ...baseRecord,
      sha256: recordHash,
    });
    previousHash = recordHash;
    immutableIndex += 1;
  }

  return evidenceChain;
}

interface ManifestExtendedGovernance {
  engineVersion?: string;
  rulePackVersions?: Record<string, string>;
  ruleCatalogSha256?: string;
  artifactHashes?: Record<string, string>;
  gateDecision?: string;
  gateVersion?: string;
  gateHash?: string;
}

function normalizeExtendedGovernance(ext?: ManifestExtendedGovernance): Record<string, unknown> | null {
  if (!ext) return null;
  const hasAny = Boolean(
    ext.engineVersion ||
      ext.rulePackVersions ||
      ext.ruleCatalogSha256 ||
      ext.artifactHashes ||
      ext.gateDecision ||
      ext.gateVersion ||
      ext.gateHash
  );
  if (!hasAny) return null;

  const sortRecord = (rec?: Record<string, string>) =>
    rec
      ? Object.fromEntries(Object.entries(rec).sort(([a], [b]) => a.localeCompare(b)))
      : undefined;

  return {
    engineVersion: ext.engineVersion || null,
    rulePackVersions: sortRecord(ext.rulePackVersions) || null,
    ruleCatalogSha256: ext.ruleCatalogSha256 || null,
    artifactHashes: sortRecord(ext.artifactHashes) || null,
    gateDecision: ext.gateDecision || null,
    gateVersion: ext.gateVersion || null,
    gateHash: ext.gateHash || null,
  };
}

function buildManifestPayloadSha256(params: {
  runId: string;
  algorithmVersion: string;
  evidenceChain: EvidenceRecord[];
  extendedGovernance?: ManifestExtendedGovernance;
}): { merkleOrChainRootSha256: string; manifestPayloadSha256: string; sourceHashes: string[]; toolsHash: string; resultsHash: string } {
  const { runId, algorithmVersion, evidenceChain, extendedGovernance } = params;
  const merkleOrChainRootSha256 =
    evidenceChain.length > 0
      ? evidenceChain[evidenceChain.length - 1]!.sha256
      : GENESIS_EVIDENCE_HASH;

  const sourceHashes = Array.from(
    new Set(evidenceChain.map((e) => e.sourceHash).filter((h): h is string => Boolean(h && h !== 'UNVERIFIED')))
  );
  const toolsHash = sha256Hex(
    JSON.stringify(
      evidenceChain
        .filter((e) => e.evidenceType === 'TOOL_RAW_OUTPUT')
        .map((e) => ({ toolName: e.toolName, toolVersion: e.toolVersion, sha256: e.sha256 }))
    )
  );
  const resultsHash = sha256Hex(
    JSON.stringify(
      evidenceChain
        .filter((e) => e.evidenceType !== 'TOOL_RAW_OUTPUT')
        .map((e) => ({ id: e.id, sha256: e.sha256 }))
    )
  );

  const normalizedExt = normalizeExtendedGovernance(extendedGovernance);
  const baseBody: Record<string, unknown> = {
    runId,
    algorithmVersion,
    recordsCount: evidenceChain.length,
    genesisHash: GENESIS_EVIDENCE_HASH,
    merkleOrChainRootSha256,
    recordHashes: evidenceChain.map((r) => ({
      index: r.immutableIndex,
      id: r.id,
      sha256: r.sha256,
      prev: r.previousRecordSha256,
    })),
  };
  if (normalizedExt) {
    baseBody.extendedGovernance = normalizedExt;
  }

  const manifestCanonicalBody = JSON.stringify(baseBody);

  return {
    merkleOrChainRootSha256,
    manifestPayloadSha256: sha256Hex(manifestCanonicalBody),
    sourceHashes,
    toolsHash,
    resultsHash,
  };
}

/**
 * Gera e assina o manifesto com HMAC-SHA256 + Ed25519 assimétrico.
 * IMPORTANTE (AC-13): Um manifesto recém-assinado recebe verificationState = 'SIGNED' e verified = false
 * até que verifyEvidenceChainAndManifest() execute e valide a cadeia + assinaturas criptográficas.
 */
export function signEvidenceManifestHmacSha256(params: {
  runId: string;
  algorithmVersion: string;
  evidenceChain: EvidenceRecord[];
  signingKeyId?: string;
  generatedAt?: string;
  secret?: string;
  includeEd25519?: boolean;
  engineVersion?: string;
  rulePackVersions?: Record<string, string>;
  ruleCatalogSha256?: string;
  artifactHashes?: Record<string, string>;
  gateDecision?: string;
  gateVersion?: string;
  gateHash?: string;
}): SignedEvidenceManifest {
  const activeKey = KeyManagementService.getActiveEvidenceHmacKey();
  const {
    runId,
    algorithmVersion,
    evidenceChain,
    signingKeyId = activeKey.keyId,
    generatedAt = new Date().toISOString(),
    secret = activeKey.secret,
    includeEd25519 = true,
    engineVersion,
    rulePackVersions,
    ruleCatalogSha256,
    artifactHashes,
    gateDecision,
    gateVersion,
    gateHash,
  } = params;

  const extendedGovernance: ManifestExtendedGovernance = {
    engineVersion,
    rulePackVersions,
    ruleCatalogSha256,
    artifactHashes,
    gateDecision,
    gateVersion,
    gateHash,
  };

  const {
    merkleOrChainRootSha256,
    manifestPayloadSha256,
    sourceHashes,
    toolsHash,
    resultsHash,
  } = buildManifestPayloadSha256({ runId, algorithmVersion, evidenceChain, extendedGovernance });

  const digitalSignatureHmacSha256 = hmacSha256Hex(manifestPayloadSha256, secret);

  let ed25519Signature: string | undefined;
  let ed25519PublicKeyPem: string | undefined;
  let ed25519KeyId: string | undefined;

  if (includeEd25519) {
    try {
      const edKey = KeyManagementService.getActiveEvidenceEd25519Key();
      const sigBuf = crypto.sign(null, Buffer.from(manifestPayloadSha256, 'utf8'), edKey.privateKeyPem);
      ed25519Signature = sigBuf.toString('base64');
      ed25519PublicKeyPem = edKey.publicKeyPem;
      ed25519KeyId = edKey.keyId;
    } catch {
      // If Ed25519 keystore read failed, omit rather than fabricating
    }
  }

  return {
    manifestId: `manifest-${runId}`,
    runId,
    algorithmVersion,
    generatedAt,
    recordsCount: evidenceChain.length,
    genesisHash: GENESIS_EVIDENCE_HASH,
    merkleOrChainRootSha256,
    rootChainSha256: merkleOrChainRootSha256,
    manifestPayloadSha256,
    sourceHashes,
    toolsHash,
    resultsHash,
    ...(engineVersion ? { engineVersion } : {}),
    ...(rulePackVersions ? { rulePackVersions } : {}),
    ...(ruleCatalogSha256 ? { ruleCatalogSha256 } : {}),
    ...(artifactHashes ? { artifactHashes } : {}),
    ...(gateDecision ? { gateDecision } : {}),
    ...(gateVersion ? { gateVersion } : {}),
    ...(gateHash ? { gateHash } : {}),
    digitalSignatureHmacSha256,
    hmacSignature: digitalSignatureHmacSha256,
    ed25519Signature,
    ed25519PublicKeyPem,
    ed25519KeyId,
    signatureAlgorithm: ed25519Signature ? 'HMAC-SHA256+ED25519' : 'HMAC-SHA256',
    signingKeyId,
    keyId: signingKeyId,
    authenticityProofType: ed25519Signature
      ? 'HMAC_SHA256_AND_ED25519_ASYMMETRIC'
      : 'HMAC_SHA256_PROTECTED_SERVER_KEY',
    integrityNote:
      'Hash SHA-256 encadeado protege a cadeia de evidências; manifesto assinado com HMAC-SHA256 + Ed25519 aguarda verificação formal.',
    verificationState: 'SIGNED',
    verified: false,
  };
}

export interface EvidenceChainVerificationResult {
  valid: boolean;
  verificationState: ManifestVerificationState;
  chainIntegrityValid: boolean;
  manifestSignatureValid: boolean;
  signatureValid: boolean;
  ed25519SignatureValid: boolean | null;
  recordsChecked: number;
  tamperedRecordIds: string[];
  tamperedIndices: number[];
  brokenLinkIndices: number[];
  expectedRootHash: string;
  actualRootHash: string;
  verificationTimestamp: string;
  message: string;
  details: string[];
}

export function verifyEvidenceChainAndManifest(
  evidenceChain: EvidenceRecord[],
  signedManifest?: SignedEvidenceManifest,
  secret?: string
): EvidenceChainVerificationResult {
  const tamperedRecordIds: string[] = [];
  const tamperedIndicesSet = new Set<number>();
  const brokenLinkIndices: number[] = [];
  const details: string[] = [];

  let expectedPrevHash = GENESIS_EVIDENCE_HASH;

  for (let i = 0; i < evidenceChain.length; i++) {
    const rec = evidenceChain[i]!;
    if (rec.immutableIndex !== i) {
      brokenLinkIndices.push(i);
      tamperedIndicesSet.add(i);
      tamperedIndicesSet.add(i + 1);
      details.push(
        `Índice fora de sequência na posição ${i}: esperado ${i}, encontrado ${rec.immutableIndex}.`
      );
    }
    if (rec.previousRecordSha256 !== expectedPrevHash) {
      brokenLinkIndices.push(i);
      tamperedIndicesSet.add(i);
      tamperedIndicesSet.add(i + 1);
      details.push(
        `Quebra de encadeamento no registro ${rec.id} (índice ${i}): previousRecordSha256 diverge do hash anterior.`
      );
    }

    const { sha256, ...rest } = rec;
    const recomputedHash = computeCanonicalEvidenceHash(rest, rec.previousRecordSha256);
    if (recomputedHash !== sha256) {
      tamperedRecordIds.push(rec.id);
      tamperedIndicesSet.add(i);
      tamperedIndicesSet.add(i + 1);
      details.push(
        `Adulteração detectada no registro ${rec.id} (índice ${i}): SHA-256 recalculado (${recomputedHash.slice(0, 12)}...) difere do armazenado (${sha256.slice(0, 12)}...).`
      );
    }

    expectedPrevHash = sha256;
  }

  const actualRootHash =
    evidenceChain.length > 0
      ? evidenceChain[evidenceChain.length - 1]!.sha256
      : GENESIS_EVIDENCE_HASH;

  const chainIntegrityValid =
    tamperedRecordIds.length === 0 && brokenLinkIndices.length === 0;

  let manifestSignatureValid = false;
  let ed25519SignatureValid: boolean | null = null;
  let verificationState: ManifestVerificationState = 'UNVERIFIABLE';
  let expectedRootHash = actualRootHash;

  if (!signedManifest) {
    details.push('Manifesto assinado ausente na execução.');
    verificationState = chainIntegrityValid ? 'UNVERIFIABLE' : 'TAMPERED';
  } else {
    expectedRootHash = signedManifest.merkleOrChainRootSha256;
    if (signedManifest.recordsCount !== evidenceChain.length) {
      details.push(
        `Divergência na contagem de registros do manifesto: manifesto=${signedManifest.recordsCount}, cadeia=${evidenceChain.length}.`
      );
    }
    if (signedManifest.merkleOrChainRootSha256 !== actualRootHash) {
      details.push(
        `Raiz da cadeia no manifesto (${signedManifest.merkleOrChainRootSha256.slice(0, 12)}...) difere da raiz atual da cadeia (${actualRootHash.slice(0, 12)}...).`
      );
    }

    const { manifestPayloadSha256 } = buildManifestPayloadSha256({
      runId: signedManifest.runId,
      algorithmVersion: signedManifest.algorithmVersion,
      evidenceChain,
      extendedGovernance: {
        engineVersion: signedManifest.engineVersion,
        rulePackVersions: signedManifest.rulePackVersions,
        ruleCatalogSha256: signedManifest.ruleCatalogSha256,
        artifactHashes: signedManifest.artifactHashes,
        gateDecision: signedManifest.gateDecision,
        gateVersion: signedManifest.gateVersion,
        gateHash: signedManifest.gateHash,
      },
    });

    const resolvedSecret =
      secret ||
      KeyManagementService.getEvidenceSecretByKeyId(signedManifest.signingKeyId) ||
      null;

    let hmacValid = false;
    if (!resolvedSecret) {
      details.push(`Chave HMAC ${signedManifest.signingKeyId} indisponível para verificação.`);
    } else {
      const expectedHmac = hmacSha256Hex(manifestPayloadSha256, resolvedSecret);
      const a = Buffer.from(expectedHmac, 'hex');
      const b = Buffer.from(signedManifest.digitalSignatureHmacSha256 || '', 'hex');
      hmacValid = a.length === b.length && crypto.timingSafeEqual(a, b);
    }

    if (signedManifest.ed25519Signature) {
      const pubPem =
        (signedManifest.ed25519KeyId
          ? KeyManagementService.getEd25519PublicKeyByKeyId(signedManifest.ed25519KeyId)
          : null) || signedManifest.ed25519PublicKeyPem;

      if (!pubPem) {
        ed25519SignatureValid = false;
        details.push('Chave pública Ed25519 indisponível para validar assinatura assimétrica.');
      } else {
        try {
          ed25519SignatureValid = crypto.verify(
            null,
            Buffer.from(manifestPayloadSha256, 'utf8'),
            pubPem,
            Buffer.from(signedManifest.ed25519Signature, 'base64')
          );
        } catch {
          ed25519SignatureValid = false;
        }
      }
    }

    const payloadMatched = manifestPayloadSha256 === signedManifest.manifestPayloadSha256;
    const rootMatched = signedManifest.merkleOrChainRootSha256 === actualRootHash;
    const countMatched = signedManifest.recordsCount === evidenceChain.length;
    const asymOk = ed25519SignatureValid === null ? true : ed25519SignatureValid;

    if (hmacValid && asymOk && payloadMatched && rootMatched && countMatched && chainIntegrityValid) {
      manifestSignatureValid = true;
      verificationState = 'VERIFIED';
      details.push(
        ed25519SignatureValid
          ? 'Cadeia SHA-256, HMAC-SHA256 e assinatura assimétrica Ed25519 verificadas com sucesso (0 adulterações).'
          : 'Assinatura HMAC-SHA256 e cadeia de custódia SHA-256 verificadas com sucesso (0 adulterações).'
      );
    } else if (!chainIntegrityValid || !payloadMatched || !rootMatched || !countMatched) {
      verificationState = 'TAMPERED';
      details.push('Adulteração detectada na cadeia de evidências ou no payload do manifesto.');
    } else if (!resolvedSecret && ed25519SignatureValid === null) {
      verificationState = 'UNVERIFIABLE';
    } else {
      verificationState = 'INVALID';
      details.push('Assinatura criptográfica (HMAC-SHA256 / Ed25519) inválida.');
    }
  }

  const valid = chainIntegrityValid && manifestSignatureValid;
  const tamperedIndices = Array.from(tamperedIndicesSet).sort((a, b) => a - b);

  return {
    valid,
    verificationState,
    chainIntegrityValid,
    manifestSignatureValid,
    signatureValid: manifestSignatureValid,
    ed25519SignatureValid,
    recordsChecked: evidenceChain.length,
    tamperedRecordIds,
    tamperedIndices,
    brokenLinkIndices,
    expectedRootHash,
    actualRootHash,
    verificationTimestamp: new Date().toISOString(),
    message: details.join(' '),
    details,
  };
}
