import { spawn, type SpawnOptions } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import type { SonarScannerType } from '../../types/benchmark';

export interface SonarReportTaskMetadata {
  projectKey: string;
  serverUrl: string;
  serverVersion?: string;
  dashboardUrl?: string;
  ceTaskId: string;
  ceTaskUrl?: string;
  reportTaskPath: string;
}

export interface ExecuteSonarScannerParams {
  scannerType: SonarScannerType;
  executablePath: string;
  projectBaseDir: string;
  propertiesContent: string;
  sonarToken?: string;
  timeoutMs?: number;
  maxMemoryMb?: number;
}

export interface ExecuteSonarScannerResult {
  executed: boolean;
  exitCode: number | null;
  timedOut: boolean;
  durationMs: number;
  stdout: string;
  stderr: string;
  reportTask: SonarReportTaskMetadata | null;
  errorMessage: string | null;
}

const FORBIDDEN_METACHAR_REGEX = /[&|;`$><\r\n\0]/;

function validateSafeArg(arg: string, label: string): void {
  if (FORBIDDEN_METACHAR_REGEX.test(arg)) {
    throw new Error(
      `SCANNER_UNSAFE_ARGUMENT_BLOCKED: Parâmetro '${label}' contém metacaracteres proibidos de interpretador de comandos.`
    );
  }
}

function quoteWindowsCmdArgument(arg: string): string {
  validateSafeArg(arg, arg);
  if (/[\s()^%!]/.test(arg)) {
    return `"${arg.replace(/"/g, '""')}"`;
  }
  return arg;
}

/**
 * SonarScannerExecutor (Seção 5.5 e FASE 3)
 * Executa o binário oficial do SonarScanner em um processo filho isolado (`shell: false`),
 * suporta scripts `.bat`/`.cmd` no Windows 10/11 (mesmo em caminhos com espaços e parênteses como
 * `C:\Program Files (x86)\...`), passa `SONAR_TOKEN` exclusivamente via variável de ambiente,
 * grava arquivo temporário `.winhood-sonar-*.properties` sem sobrescrever `sonar-project.properties`
 * existente do usuário e recupera `ceTaskId` de `.scannerwork/report-task.txt`.
 */
export class SonarScannerExecutor {
  /**
   * Constrói a especificação segura de execução multi-plataforma (Linux/macOS/Windows).
   * No Windows, executáveis `.bat` e `.cmd` (`sonar-scanner.bat`, `mvn.cmd`, `gradlew.bat`, `npx.cmd`)
   * não podem ser iniciados diretamente via `CreateProcess` com `shell: false` (lançam `EINVAL` no Node.js).
   * Este método valida rigorosamente cada argumento contra metacaracteres e invoca `cmd.exe /d /s /c`
   * com `windowsVerbatimArguments: true` e `shell: false`.
   */
  public static buildPlatformSafeSpawnSpec(
    executablePath: string,
    args: string[],
    platform: NodeJS.Platform = process.platform
  ): {
    command: string;
    args: string[];
    options: Pick<SpawnOptions, 'shell' | 'windowsVerbatimArguments' | 'windowsHide'>;
  } {
    validateSafeArg(executablePath, 'executablePath');
    for (const arg of args) {
      validateSafeArg(arg, 'scannerArg');
    }

    const isWin = platform === 'win32';
    const lowerExec = executablePath.toLowerCase();
    const isWinBatchScript =
      isWin &&
      (lowerExec.endsWith('.bat') ||
        lowerExec.endsWith('.cmd') ||
        lowerExec === 'npx' ||
        lowerExec === 'mvn' ||
        lowerExec === 'gradle');

    if (isWinBatchScript) {
      const comSpec =
        process.env.ComSpec ||
        path.win32.join(process.env.SystemRoot || 'C:\\Windows', 'System32', 'cmd.exe');
      const quotedCmd = quoteWindowsCmdArgument(executablePath);
      const quotedArgs = args.map((a) => quoteWindowsCmdArgument(a)).join(' ');
      const innerCommandLine = `"${quotedCmd}${quotedArgs ? ` ${quotedArgs}` : ''}"`;
      return {
        command: comSpec,
        args: ['/d', '/s', '/c', innerCommandLine],
        options: {
          shell: false,
          windowsVerbatimArguments: true,
          windowsHide: true,
        },
      };
    }

    return {
      command: executablePath,
      args,
      options: {
        shell: false,
        windowsHide: true,
      },
    };
  }

  public static parseReportTaskFile(reportTaskPath: string): SonarReportTaskMetadata | null {
    try {
      if (!fs.existsSync(reportTaskPath)) return null;
      const raw = fs.readFileSync(reportTaskPath, 'utf8');
      const map: Record<string, string> = {};
      for (const line of raw.split(/\r?\n/)) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;
        const eq = trimmed.indexOf('=');
        if (eq > 0) {
          map[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
        }
      }
      if (!map.ceTaskId || !map.projectKey) return null;
      return {
        projectKey: map.projectKey,
        serverUrl: map.serverUrl || '',
        serverVersion: map.serverVersion,
        dashboardUrl: map.dashboardUrl,
        ceTaskId: map.ceTaskId,
        ceTaskUrl: map.ceTaskUrl,
        reportTaskPath,
      };
    } catch {
      return null;
    }
  }

  public static async executeIsolatedScanner(
    params: ExecuteSonarScannerParams
  ): Promise<ExecuteSonarScannerResult> {
    const startMs = performance.now();
    const timeoutMs = params.timeoutMs ?? 120_000;
    const maxMemMb = params.maxMemoryMb ?? 1024;

    if (!params.projectBaseDir || !fs.existsSync(params.projectBaseDir)) {
      return {
        executed: false,
        exitCode: null,
        timedOut: false,
        durationMs: 0,
        stdout: '',
        stderr: '',
        reportTask: null,
        errorMessage: `Diretório base do projeto não existe no host: ${params.projectBaseDir}`,
      };
    }

    if (!params.executablePath) {
      return {
        executed: false,
        exitCode: null,
        timedOut: false,
        durationMs: 0,
        stdout: '',
        stderr: '',
        reportTask: null,
        errorMessage: `Executável do scanner (${params.scannerType}) não localizado.`,
      };
    }

    // Gravar arquivo temporário dedicado (.winhood-sonar-*.properties) com UUID CSPRNG para NUNCA
    // sobrescrever sonar-project.properties existente nem usar PRNG previsível (typescript:S2245)
    const tempPropsFileName = `.winhood-sonar-${crypto.randomUUID()}.properties`;
    const propsFilePath = path.join(params.projectBaseDir, tempPropsFileName);

    try {
      fs.writeFileSync(propsFilePath, params.propertiesContent, { encoding: 'utf8', mode: 0o600 });
    } catch (writeErr: any) {
      return {
        executed: false,
        exitCode: null,
        timedOut: false,
        durationMs: 0,
        stdout: '',
        stderr: '',
        reportTask: null,
        errorMessage: `Não foi possível gravar arquivo temporário de propriedades do scanner: ${writeErr?.message || String(writeErr)}`,
      };
    }

    const cleanupTempProps = () => {
      try {
        if (fs.existsSync(propsFilePath)) {
          fs.unlinkSync(propsFilePath);
        }
      } catch {
        // Ignore cleanup errors
      }
    };

    const childEnv: NodeJS.ProcessEnv = {
      ...process.env,
      SONAR_SCANNER_OPTS: `-Xmx${maxMemMb}m`,
    };
    if (params.sonarToken && params.sonarToken.trim().length > 0) {
      childEnv.SONAR_TOKEN = params.sonarToken.trim();
    } else {
      delete childEnv.SONAR_TOKEN;
    }

    let rawCommand = params.executablePath;
    let rawArgs: string[] = [`-Dproject.settings=${propsFilePath}`];

    if (params.scannerType === 'SONAR_SCANNER_MAVEN') {
      rawCommand = params.executablePath;
      rawArgs = ['sonar:sonar', '-B'];
    } else if (params.scannerType === 'SONAR_SCANNER_GRADLE') {
      rawCommand = params.executablePath;
      rawArgs = ['sonar', '--no-daemon'];
    } else if (params.scannerType === 'SONAR_SCANNER_NPM') {
      rawCommand = process.platform === 'win32' ? 'npx.cmd' : 'npx';
      rawArgs = ['--yes', '@sonar/scan', `-Dproject.settings=${propsFilePath}`];
    }

    let spawnSpec: ReturnType<typeof SonarScannerExecutor.buildPlatformSafeSpawnSpec>;
    try {
      spawnSpec = SonarScannerExecutor.buildPlatformSafeSpawnSpec(rawCommand, rawArgs);
    } catch (valErr: any) {
      cleanupTempProps();
      return {
        executed: false,
        exitCode: null,
        timedOut: false,
        durationMs: Math.round(performance.now() - startMs),
        stdout: '',
        stderr: '',
        reportTask: null,
        errorMessage: valErr?.message || String(valErr),
      };
    }

    return new Promise((resolve) => {
      let stdout = '';
      let stderr = '';
      let timedOut = false;

      let child;
      try {
        child = spawn(spawnSpec.command, spawnSpec.args, {
          cwd: params.projectBaseDir,
          env: childEnv,
          ...spawnSpec.options,
          stdio: ['ignore', 'pipe', 'pipe'],
        });
      } catch (err: any) {
        cleanupTempProps();
        resolve({
          executed: false,
          exitCode: null,
          timedOut: false,
          durationMs: Math.round(performance.now() - startMs),
          stdout: '',
          stderr: '',
          reportTask: null,
          errorMessage: `Falha ao iniciar processo isolado do scanner: ${err?.message || String(err)}`,
        });
        return;
      }

      const timer = setTimeout(() => {
        timedOut = true;
        child.kill('SIGTERM');
      }, timeoutMs);

      child.stdout?.on('data', (chunk: Buffer) => {
        if (stdout.length < 32_000) stdout += chunk.toString('utf8');
      });
      child.stderr?.on('data', (chunk: Buffer) => {
        if (stderr.length < 16_000) stderr += chunk.toString('utf8');
      });

      const redact = (s: string) =>
        params.sonarToken
          ? s.split(params.sonarToken).join('[SONAR_TOKEN_REDACTED]')
          : s;

      child.on('error', (err) => {
        clearTimeout(timer);
        cleanupTempProps();
        resolve({
          executed: false,
          exitCode: null,
          timedOut,
          durationMs: Math.round(performance.now() - startMs),
          stdout: redact(stdout),
          stderr: redact(stderr),
          reportTask: null,
          errorMessage: err.message,
        });
      });

      child.on('close', (code) => {
        clearTimeout(timer);
        cleanupTempProps();
        const durationMs = Math.max(1, Math.round(performance.now() - startMs));
        const reportTaskCandidates = [
          path.join(params.projectBaseDir, '.scannerwork', 'report-task.txt'),
          path.join(params.projectBaseDir, 'target', 'sonar', 'report-task.txt'),
          path.join(params.projectBaseDir, 'build', 'sonar', 'report-task.txt'),
        ];
        let reportTask: SonarReportTaskMetadata | null = null;
        for (const candidate of reportTaskCandidates) {
          const parsed = SonarScannerExecutor.parseReportTaskFile(candidate);
          if (parsed) {
            reportTask = parsed;
            break;
          }
        }

        resolve({
          executed: true,
          exitCode: code,
          timedOut,
          durationMs,
          stdout: redact(stdout),
          stderr: redact(stderr),
          reportTask,
          errorMessage: timedOut
            ? `Scanner excedeu o timeout configurado de ${timeoutMs}ms.`
            : code !== 0
              ? `Scanner retornou código de saída ${code}.`
              : null,
        });
      });
    });
  }
}
